// <Scene>: the 32-second threshold, 768 frames, one manifest frame per video frame (frame-exact with the score).
import React from 'react';
import {AbsoluteFill, useCurrentFrame} from 'remotion';
import {clamp} from '../lib/math.ts';
import {W, H, setCameraTime} from '../lib/camera.ts';
import {Defs, Sky, Yard, Room, Facade, Frame, Porch, Railing} from './World.tsx';
import {Dog, Person} from './Actors.tsx';
// @ts-ignore  generated by build/solve.ts
import manifest from '../../cache/manifest.json';
export const M: any = manifest;

export const Scene: React.FC<{matte?: boolean; captions?: boolean}> = ({matte, captions = true}) => {
  const i = Math.min(M.frames.length - 1, useCurrentFrame());
  const F = M.frames[i];
  const t = F.t, angle = F.door.angle, lamp = F.door.lamp, dusk = 0.4 + 0.6 * clamp(t / 32);
  setCameraTime(t);           // the camera is part of the frame's data: set before anything projects
  if (matte) return (
    <AbsoluteFill style={{background: '#000'}}>
      <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`}><Defs angle={angle}/>
        <Dog pose={F.dog} angle={angle} lamp={lamp} clip="opening" matte dusk={dusk}/></svg>
    </AbsoluteFill>
  );
  const cap = F.caption;
  return (
    <AbsoluteFill style={{background: '#101222'}}>
      <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`}>
        <Defs angle={angle}/>
        <Sky t={t}/>
        <Yard t={t}/>
        <Room lamp={lamp} angle={angle}/>
        <Facade t={t} lamp={lamp}/>
        <Frame lamp={lamp}/>
        <Porch t={t} lamp={lamp} angle={angle}/>
        <Railing t={t} lamp={lamp}/>
        <Person pose={F.person} angle={angle} lamp={lamp} clip="opening" dusk={dusk}/>
        <Dog pose={F.dog} angle={angle} lamp={lamp} clip="opening" dusk={dusk}/>
        <rect width={W} height={H} fill="url(#vignette)"/>
        <defs><radialGradient id="vignette" cx="0.5" cy="0.5" r="0.75"><stop offset="0.6" stopColor="#000" stopOpacity="0"/><stop offset="1" stopColor="#000" stopOpacity="0.45"/></radialGradient></defs>
      </svg>
      {captions && cap ? (
        <div style={{position: 'absolute', left: 0, right: 0, bottom: cap.kind === 'call' ? 58 : 54, textAlign: 'center', opacity: cap.alpha,
          fontFamily: 'Literata', fontStyle: 'italic', fontSize: cap.kind === 'call' ? 34 : 25, letterSpacing: cap.kind === 'call' ? 0.5 : 1.2,
          color: cap.kind === 'call' ? '#f6efe2' : '#e9d3ad', textShadow: '0 2px 10px rgba(0,0,0,0.8)'}}>{cap.text}</div>
      ) : null}
    </AbsoluteFill>
  );
};
